section(ui, app, i18n::t(Key::SettingsSectionLanguage));
widgets::setting_row(
    ui,
    &palette,
    i18n::t(Key::SettingsLanguageLabel),
    i18n::t(Key::SettingsLanguageHint),
    |ui| {
        ui.with_layout(egui::Layout::top_down(egui::Align::Max), |ui| {
            let selected = app.settings.language.label();
            let response = egui::ComboBox::from_id_salt("language")
                .selected_text(" ")
                .width(200.0_f32.min(ui.available_width()))
                .show_ui(ui, |ui| {
                    for language in Language::ALL {
                        if wallpaper_option(
                            ui,
                            &palette,
                            language.label(),
                            app.settings.language == language,
                        )
                        .clicked()
                        {
                            app.settings.language = language;
                            i18n::set_language(language);
                            app.actions.push(Action::SettingsChanged);
                        }
                    }
                });
            let rect = response.response.rect;
            let text = widgets::line(
                ui,
                selected,
                theme::regular(14.0),
                palette.text,
                rect.width() - 36.0,
                1,
            );
            text.paint(
                ui,
                egui::pos2(
                    rect.left() + 8.0,
                    rect.center().y - text.size().y / 2.0,
                ),
                palette.text,
            );
            response.response.widget_info(|| {
                let mut info = egui::WidgetInfo::labeled(
                    egui::WidgetType::ComboBox,
                    ui.is_enabled(),
                    i18n::t(Key::SettingsLanguageLabel),
                );
                info.current_text_value = Some(selected.to_owned());
                info
            });
        });
    },
);

